  [[maybe_unused]] uint64_t dpp_old_exec_ = wf.exec();
  if (inst_.src0 == amdgpu::SRC_DPP)
    amdgpu::dpp::apply_dpp(src0, dpp_plan_, dpp_old_exec_, dpp_src0_, wf);
